const routes=[
 {id:'qa',n:'01',icon:'Q',title:'QA & Testing',desc:'Strategy, defects, and quality.',color:'#d6ff43'},
 {id:'playwright',n:'02',icon:'P',title:'Playwright & Automation',desc:'E2E, Selenium, and framework design.',color:'#65d9ff'},
 {id:'engineering',n:'03',icon:'{}',title:'Engineering',desc:'Java, APIs, Git, CI/CD, and web.',color:'#b99cff'},
 {id:'ai',n:'04',icon:'AI',title:'AI Automation',desc:'Agents, MCP, and orchestration.',color:'#ffb66d'},
 {id:'ops',n:'05',icon:'O',title:'Operations',desc:'Observability, IoT, and reliability.',color:'#ff89b5'}
];
const questions=[];
const baseTags={qa:['Quality Assurance','Manual Testing'],playwright:['Test Automation','Playwright'],engineering:['Software Engineering'],ai:['AI Automation','LLMs'],ops:['Technical Operations','Observability']};
const tagRules=[[/selenium|webdriver|xpath|stale element/i,'Selenium'],[/testng/i,'TestNG'],[/rest assured/i,'Rest Assured'],[/jdbc/i,'JDBC'],[/playwright|browser context|trace/i,'Playwright'],[/typescript|\bts\b/i,'TypeScript'],[/javascript|\bjs\b|node\.js/i,'JavaScript'],[/python|pytest|pydantic|fastapi/i,'Python'],[/\bjava\b|string|hashmap|linked list|singleton|exception|oop/i,'Java'],[/api|http|rest assured|json|webhook|bearer/i,'API Testing'],[/git|merge|rebase|commit|push/i,'Git'],[/jenkins|github actions|ci\/cd|pipeline/i,'CI/CD'],[/sql|database|transaction|indexing|jdbc/i,'SQL'],[/docker|container/i,'Docker'],[/accessibility|role-|label/i,'Accessibility Testing'],[/performance|execution time|capacity/i,'Performance Testing'],[/security|authentication|authorization|secrets|tls|bearer/i,'Security Testing'],[/mcp/i,'Model Context Protocol'],[/rag|retrieval|embedding|vector/i,'RAG'],[/prompt|agent|tool calling|function calling/i,'AI Agents'],[/mqtt|iot|home assistant/i,'IoT'],[/incident|alert|logging|tracing|runbook|slo/i,'Reliability Engineering']];
function tagsFor(r,q){const tags=[...baseTags[r]];tagRules.forEach(([rule,tag])=>{if(rule.test(q)&&!tags.includes(tag))tags.push(tag)});return tags;}
function add(r,q,correct,e){const wrong=['Rely on fixed sleeps and assumptions','Ignore the evidence and rerun without investigating','Treat it as a UI-only concern'];const c=(questions.length*3)%4;const a=[...wrong];a.splice(c,0,correct);questions.push({r,q,a,c,e,tags:tagsFor(r,q)});}
let active=[],index=0,score=0,answered=false,currentRoute='',selectedTag='all',selectedProgressFilter='all';const panel=document.querySelector('#questionPanel');const grid=document.querySelector('#routeGrid');const tagFilter=document.querySelector('#tagFilter');const questionCount=document.querySelector('#questionCount');const progressFilter=document.querySelector('#progressFilter');
const progressStorageKey='qa-ai-learning-platform-progress-v1';
function questionProgressKey(question){let hash=5381;const source=`${question.r}|${question.q}`;for(let cursor=0;cursor<source.length;cursor++)hash=(hash*33)^source.charCodeAt(cursor);return `q-${hash>>>0}`}
function loadSavedProgress(){try{const stored=window.localStorage.getItem(progressStorageKey);return stored?JSON.parse(stored):{}}catch{return {}}}
let savedProgress=loadSavedProgress();
function saveQuestionProgress(question,isCorrect){const key=questionProgressKey(question),previous=savedProgress[key]||{attempts:0};savedProgress[key]={attempts:previous.attempts+1,correct:Boolean(previous.correct||isCorrect),lastAnswered:new Date().toISOString()};try{window.localStorage.setItem(progressStorageKey,JSON.stringify(savedProgress))}catch{}}
function savedQuestionCount(){return Object.keys(savedProgress).length}
function historyMarker(question){const previous=savedProgress[questionProgressKey(question)];return previous?`<span class="history-badge">${previous.correct?'PREVIOUSLY CORRECT':'PREVIOUSLY ANSWERED'}</span>`:''}
routes.forEach(r=>{const el=document.createElement('article');el.className='route';el.style.setProperty('--route',r.color);el.innerHTML=`<span class="route-num">${r.n} / MODULE</span><span class="route-icon">${r.icon}</span><h3>${r.title}</h3><p>${r.desc}</p><button>OPEN PATH →</button>`;el.onclick=()=>start(r.id);grid.append(el)});
const totalQuestionCount=questions.length;document.querySelector('.metrics strong').textContent=totalQuestionCount;const availableTags=[...new Set(questions.flatMap(q=>q.tags))].sort();availableTags.forEach(tag=>tagFilter.add(new Option(tag,tag)));tagFilter.onchange=()=>{selectedTag=tagFilter.value};progressFilter.onchange=()=>{selectedProgressFilter=progressFilter.value};document.querySelector('#startFiltered').onclick=()=>start('all');
const startAllButton=document.querySelector('#startAll');if(startAllButton)startAllButton.onclick=()=>{tagFilter.value='all';selectedTag='all';start('all')};document.querySelector('#restart').onclick=()=>start(currentRoute);const clearSavedProgressButton=document.querySelector('#clearSavedProgress');if(clearSavedProgressButton)clearSavedProgressButton.onclick=()=>{if(window.confirm('Clear all saved question progress on this device?')){savedProgress={};try{window.localStorage.removeItem(progressStorageKey)}catch{};clearSavedProgressButton.textContent='Saved progress cleared';setTimeout(()=>{clearSavedProgressButton.textContent='Clear saved progress'},1800)}};
function shuffle(items){for(let i=items.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]]}return items}
function start(route){currentRoute=route;const requested=Number(questionCount.value);active=shuffle(questions.filter(x=>{const previous=savedProgress[questionProgressKey(x)];const matchesRoute=route==='all'||x.r===route;const matchesTag=selectedTag==='all'||x.tags.includes(selectedTag);const matchesProgress=selectedProgressFilter==='all'||(selectedProgressFilter==='never-answered'&&!previous)||(selectedProgressFilter==='never-correct'&&!previous?.correct);return matchesRoute&&matchesTag&&matchesProgress})).slice(0,requested);index=0;score=0;document.querySelector('#restart').hidden=false;document.querySelector('#quizTitle').textContent=route==='all'?'All learning paths':routes.find(x=>x.id===route).title;document.querySelector('#quizHint').textContent=`${active.length} of ${requested} requested questions selected${selectedTag==='all'?'':` for ${selectedTag}`}. ${savedQuestionCount()} saved answers on this device.`;document.querySelector('#simulator').scrollIntoView({behavior:'smooth',block:'center'});if(!active.length){panel.innerHTML='<div class="empty-state"><h3>No matching learning activities</h3><p>Choose a different tag or start a broader practice session.</p></div>';updateProgress();return}render()}
function render(){answered=false;const q=active[index],letter=['A','B','C','D'];panel.innerHTML=`<div class="question"><div class="question-top">QUESTION ${index+1} OF ${active.length} · ${routes.find(x=>x.id===q.r).title.toUpperCase()}${historyMarker(q)}</div><h3>${q.q}</h3><div class="question-tags">${q.tags.map(tag=>`<span>${tag}</span>`).join('')}</div><div class="options">${q.a.map((x,i)=>`<button class="option" data-i="${i}"><strong>${letter[i]}</strong>${x}</button>`).join('')}</div><div id="feedback"></div></div>`;panel.querySelectorAll('.option').forEach(b=>b.onclick=()=>answer(+b.dataset.i));updateProgress()}
function answer(choice){if(answered)return;answered=true;const q=active[index],opts=panel.querySelectorAll('.option');opts.forEach((b,i)=>{b.disabled=true;if(i===q.c)b.classList.add('correct');if(i===choice&&i!==q.c)b.classList.add('wrong')});if(choice===q.c)score+=100;const good=choice===q.c;saveQuestionProgress(q,good);document.querySelector('#feedback').innerHTML=`<div class="explanation"><b>${good?'CORRECT ANSWER':'REVIEW THIS CONCEPT'}</b><p>${q.e}</p></div><button class="primary next" id="next">${index===active.length-1?'See result':'Next question →'}</button>`;document.querySelector('#next').onclick=next;updateProgress()}
function next(){index++;if(index>=active.length){panel.innerHTML=`<div class="empty-state"><div class="terminal-icon">OK</div><h3>Session completed</h3><p>You scored <b>${score}</b> out of ${active.length*100}. Repeat the path to reinforce the concepts or choose a new module.</p><button class="primary" onclick="start(currentRoute)">Repeat simulation</button></div>`;index=active.length;updateProgress();return}render()}
function updateProgress(){const total=active.length||1,pct=(index+(answered?1:0))/total*100;document.querySelector('#progressBar').style.width=pct+'%';document.querySelector('#progressText').textContent=active.length?`${Math.min(index+1,total)} / ${total} QUESTIONS`:'READY TO START';document.querySelector('#scoreText').textContent=score+' PTS'}
